function seedHash(value){let n=2166136261;for(let c of value)n=Math.imul(n^c.charCodeAt(0),16777619);return n>>>0}
function generatedPuzzle(id,seed,kind){let state=seed>>>0;const random=()=>{state=(Math.imul(state,1664525)+1013904223)>>>0;return state/4294967296};let fork=random()>.45,t=Math.floor(random()*4),dr=Math.floor(random()*5)-2,dc=Math.floor(random()*5)-2,mirror=random()>.5;const map=i=>{let r=Math.floor(i/15)+dr,c=i%15+dc;if(mirror)c=14-c;return transform(r*15+c,t)};let black=(fork?[110,111,113,82,97,127]:[109,110,111,112]).map(map),white=(fork?[64,65,66,154,155,156]:[108,79,80,94]).map(map),first=map(fork?112:113),reply=map(114);for(let j=0;j<4;j++){let i=Math.floor(random()*225);if(!black.includes(i)&&!white.includes(i)&&i!==first&&i!==reply&&Math.max(Math.abs(Math.floor(i/15)-Math.floor(first/15)),Math.abs(i%15-first%15))>4)white.push(i)}return {id,kind,title:kind==='daily'?'The daily five':fork?'Two paths to victory':'Find the finishing move',theme:fork?'Create a double threat':'Win in one move',difficulty:fork?1500:900,black,white,first,reply,steps:fork?2:1,hint:fork?'Look for a move that creates two open lines of four.':'Find four connected black stones and extend their open end.'}}
function dailyPuzzle(now=new Date()){let date=now.toISOString().slice(0,10);return generatedPuzzle('daily-'+date,seedHash('gomoku-daily-v1:'+date),'daily')}
async function resolvePuzzle(db,id,userId){let legacy=PUZZLES.find(p=>p.id===id);if(legacy)return {...legacy,steps:Number(id.slice(1))<=4?1:2};if(/^daily-\d{4}-\d{2}-\d{2}$/.test(id)){let day=id.slice(6),ms=Date.parse(day+'T00:00:00Z');if(!Number.isFinite(ms)||new Date(ms).toISOString().slice(0,10)!==day||Date.now()-ms<0||Date.now()-ms>172800000)fail('This daily puzzle has expired. Open today’s challenge.');return generatedPuzzle(id,seedHash('gomoku-daily-v1:'+day),'daily')}let session=await db.prepare('SELECT seed FROM training_sessions WHERE user_id=? AND puzzle_id=?').bind(userId,id).first();return session?generatedPuzzle(id,session.seed,'unlimited'):null}
async function trainingOverview(db,userId){let daily=dailyPuzzle(),progress=await db.prepare('SELECT solved,attempts FROM puzzle_progress WHERE user_id=? AND puzzle_id=?').bind(userId,daily.id).first(),stats=await db.prepare("SELECT COUNT(*) attempted,SUM(solved) solved FROM puzzle_progress WHERE user_id=? AND (puzzle_id LIKE 'daily-%' OR puzzle_id LIKE 'unlimited-%')").bind(userId).first(),days=(await db.prepare("SELECT puzzle_id FROM puzzle_progress WHERE user_id=? AND solved=1 AND puzzle_id LIKE 'daily-%' ORDER BY puzzle_id DESC LIMIT 366").bind(userId).all()).results;let solvedDays=new Set(days.map(d=>d.puzzle_id.slice(6))),cursor=new Date(new Date().toISOString().slice(0,10)+'T00:00:00Z'),streak=0;if(!solvedDays.has(cursor.toISOString().slice(0,10)))cursor.setUTCDate(cursor.getUTCDate()-1);while(solvedDays.has(cursor.toISOString().slice(0,10))){streak++;cursor.setUTCDate(cursor.getUTCDate()-1)}return {daily:{...puzzleView(daily),solved:!!progress?.solved,attempts:progress?.attempts||0},stats:{attempted:stats.attempted||0,solved:stats.solved||0,streak},resetsAt:new Date(Date.parse(new Date().toISOString().slice(0,10)+'T00:00:00Z')+86400000).toISOString()}}

const NPC_BANDS=[{level:'Rookie',rating:600,names:['Sprout','Pebble','Clover']},{level:'Beginner',rating:900,names:['Pip','Moss','Fern']},{level:'Intermediate',rating:1200,names:['Maple','Willow','Cedar']},{level:'Advanced',rating:1500,names:['Ember','Flint','Jade']},{level:'Expert',rating:1800,names:['Orion','Nova','Vega']},{level:'Master',rating:2100,names:['Atlas','Zenith','Sage']}];
const NPCS=NPC_BANDS.flatMap((b,band)=>b.names.map((name,style)=>({id:name.toLowerCase(),name,handle:'npc_'+name.toLowerCase(),rating:b.rating+(style-1)*50,level:b.level,band,style:['balanced','attacking','defensive'][style],color:['sage','sand','blue','rose'][band%4],bio:[`A ${b.level.toLowerCase()} opponent with a balanced approach.`,`A ${b.level.toLowerCase()} opponent who likes building threats.`,`A ${b.level.toLowerCase()} opponent who watches your connections.`][style]})));
function npcRandom(seed){let n=seedHash(seed);return()=>{n=(Math.imul(n,1664525)+1013904223)>>>0;return n/4294967296}}
function npcCandidates(board){let occupied=[];for(let i=0;i<225;i++)if(board[i])occupied.push(i);if(!occupied.length)return[112];let set=new Set();for(let i of occupied){let r=Math.floor(i/15),c=i%15;for(let dr=-2;dr<=2;dr++)for(let dc=-2;dc<=2;dc++){let y=r+dr,x=c+dc;if(y>=0&&x>=0&&y<15&&x<15&&!board[y*15+x])set.add(y*15+x)}}return [...set]}
function npcLine(board,i,p){let r=Math.floor(i/15),c=i%15;for(let[dr,dc]of DIRECTIONS){let n=1;for(let s of [-1,1])for(let k=1;k<5;k++){let y=r+dr*k*s,x=c+dc*k*s;if(y<0||x<0||y>=15||x>=15||board[y*15+x]!==p)break;n++}if(n>=5)return true}return false}
function npcScore(board,i,p){let r=Math.floor(i/15),c=i%15,total=0;for(let[dr,dc]of DIRECTIONS){let n=1,open=0;for(let s of [-1,1])for(let k=1;k<5;k++){let y=r+dr*k*s,x=c+dc*k*s;if(y<0||x<0||y>=15||x>=15)break;let v=board[y*15+x];if(v===p)n++;else{if(!v)open++;break}}if(n>=5)return 1e9;total+=n===4?(open===2?900000:open?90000:0):n===3?(open===2?16000:open?1800:0):n===2?(open===2?700:open?90:0):open*8;
// Score broken fours and threes as well as contiguous lines.
for(let start=-4;start<=0;start++){let count=0,blocked=false;for(let k=start;k<start+5;k++){let y=r+dr*k,x=c+dc*k;if(y<0||x<0||y>=15||x>=15){blocked=true;break}let v=k===0?p:board[y*15+x];if(v===3-p){blocked=true;break}if(v===p)count++}if(!blocked)total+=count===4?18000:count===3?900:count===2?40:0}}
return total+14-Math.abs(r-7)-Math.abs(c-7)}
function npcRank(board,p,style,candidates=npcCandidates(board)){let defense=style==='defensive'?1.2:style==='attacking'?.85:1;return candidates.map(i=>({i,attack:npcScore(board,i,p),defend:npcScore(board,i,3-p)})).map(m=>({...m,value:m.attack+defense*m.defend})).sort((a,b)=>b.value-a.value)}
function chooseNPCMove(board,npc,seed){let random=npcRandom(seed),rating=npc.rating,candidates=npcCandidates(board),ranked=npcRank(board,2,npc.style,candidates),wins=ranked.filter(m=>m.attack>=1e9),blocks=ranked.filter(m=>m.defend>=1e9);if(!ranked.length)return -1;
if(wins.length&&(rating>=850||random()>.18))return wins[0].i;
if(blocks.length&&(rating>=1150||random()>(rating<850?.60:.20)))return blocks[0].i;
let blunder=rating<850?.48:rating<1150?.24:rating<1450?.09:rating<1750?.025:0;
if(random()<blunder){let pool=ranked.slice(0,rating<850?14:rating<1150?7:4);return pool[Math.floor(random()*pool.length)].i}
if(rating<1450){let pool=rating<850?5:rating<1150?3:2;return ranked[Math.floor(random()*Math.min(pool,ranked.length))].i}
let width=rating>=2050?10:rating>=1750?7:4,best=ranked[0].i,bestValue=-Infinity;
for(let move of ranked.slice(0,width)){let i=move.i;board[i]=2;let replies=npcRank(board,1,'balanced'),ownWins=0;for(let j of npcCandidates(board)){if(npcLine(board,j,2)&&++ownWins===2)break}let immediate=replies.find(m=>m.attack>=1e9);let value=move.value;if(immediate)value=-2e9;else if(ownWins>=2)value=5e8;else if(rating>=1750){let worst=Infinity;for(let reply of replies.slice(0,rating>=2050?4:2)){board[reply.i]=1;let follow=npcRank(board,2,npc.style);let next=follow[0];let response=next?(next.attack>=1e9?2e8:next.value*.55):0;worst=Math.min(worst,response-reply.attack*1.15);board[reply.i]=0}value=move.attack*.7+move.defend*.5+(Number.isFinite(worst)?worst:0)}else value-=replies[0]?.attack*.8||0;board[i]=0;if(value>bestValue){bestValue=value;best=i}}
return best}

const DIRECTIONS=[[1,0],[0,1],[1,1],[1,-1]],COLORS=new Set(['sage','sand','blue','rose']);
const json=(data,status=200)=>Response.json(data,{status,headers:{'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
const fail=(message,status=400)=>{throw Object.assign(new Error(message),{status})};
function winner(moves){const b=Array(225).fill(0);for(let k=0;k<moves.length;k++){let i=moves[k];if(!Number.isInteger(i)||i<0||i>=225||b[i])return {invalid:true};b[i]=k%2+1;let p=b[i],r=Math.floor(i/15),c=i%15;for(let[dr,dc]of DIRECTIONS){let n=1;for(let s of [-1,1])for(let j=1;j<5;j++){let y=r+dr*j*s,x=c+dc*j*s;if(y<0||x<0||y>=15||x>=15||b[y*15+x]!==p)break;n++}if(n>=5)return {winner:p,board:b}}}return {winner:0,board:b}}
function transform(i,t){let r=Math.floor(i/15),c=i%15;for(let j=0;j<t;j++)[r,c]=[c,14-r];return r*15+c}
const PUZZLES=Array.from({length:8},(_,n)=>{let fork=n>=4,t=n%4;let black=fork?[110,111,113,82,97,127]:[109,110,111,112];let white=fork?[64,65,66,150,151,152]:[108,79,80,94];return {id:'p'+(n+1),title:fork?['Two ways home','Crossroads','Split the defense','An unstoppable threat'][t]:['The finishing touch','A vertical vision','Across the line','The last connection'][t],theme:fork?'Create a double threat':'Win in one move',difficulty:fork?1500:900,black:black.map(i=>transform(i,t)),white:white.map(i=>transform(i,t)),first:transform(fork?112:113,t),reply:transform(114,t),hint:fork?'Look for a move that creates two open lines of four.':'Find four connected black stones and extend their open end.'}});
