if(path==='/api/profile'&&method==='POST'){let handle=String(body.handle||'').trim().toLowerCase(),name=String(body.name||'').trim(),bio=String(body.bio||'').trim();if(handle.startsWith('npc_'))fail('Usernames beginning with npc_ are reserved for computer opponents.');if(!/^[a-z][a-z0-9_]{2,19}$/.test(handle))fail('Use 3–20 lowercase letters, numbers, or underscores. Start with a letter.');if(!name||name.length>40||bio.length>240)fail('Use a name up to 40 characters and a bio up to 240 characters.');if(await one('SELECT id FROM profiles WHERE handle=? COLLATE NOCASE AND id<>?',handle,id))fail('That username is already taken.');await run('UPDATE profiles SET handle=?,name=?,bio=?,color=? WHERE id=?',handle,name,bio,COLORS.has(body.color)?body.color:'sage',id);return json({ok:true})}
