if(path==='/api/puzzle'&&method==='POST'){let p=await resolvePuzzle(db,String(body.id||''),id);if(!p)fail('Puzzle not found.',404);let choices=body.moves;if(!Array.isArray(choices)||choices.length<1||choices.length>2||choices.some(i=>!Number.isInteger(i)))fail('Invalid puzzle attempt.');let correct=choices[0]===p.first,solved=false;if(correct&&p.steps===1)solved=true;else if(correct&&choices.length===1)return json({correct:true,solved:false,reply:p.reply,message:'Good. They blocked one line. Now finish the game.'});else if(correct){let b=Array(225).fill(0);p.black.forEach(i=>b[i]=1);p.white.forEach(i=>b[i]=2);b[p.first]=1;b[p.reply]=2;let i=choices[1];if(i>=0&&i<225&&!b[i]){b[i]=1;let r=Math.floor(i/15),c=i%15;for(let[dr,dc]of DIRECTIONS){let n=1;for(let s of [-1,1])for(let k=1;k<5;k++){let y=r+dr*k*s,x=c+dc*k*s;if(y<0||x<0||y>=15||x>=15||b[y*15+x]!==1)break;n++}if(n>=5)solved=true}}correct=solved}
await db.batch([db.prepare('INSERT OR IGNORE INTO puzzle_progress(user_id,puzzle_id) VALUES(?,?)').bind(id,p.id),db.prepare('UPDATE profiles SET puzzle_rating=puzzle_rating+? WHERE id=? AND EXISTS(SELECT 1 FROM puzzle_progress WHERE user_id=? AND puzzle_id=? AND rated=0)').bind(body.assisted?0:solved?12:-8,id,id,p.id),db.prepare('UPDATE puzzle_progress SET attempts=attempts+1,solved=MAX(solved,?),rated=1 WHERE user_id=? AND puzzle_id=?').bind(solved?1:0,id,p.id)]);return json({correct,solved,message:solved?'Beautifully played. Puzzle solved.':'Not quite. Look for a stronger move.',profile:await one('SELECT * FROM profiles WHERE id=?',id)})}
if(path==='/api/npcs'&&method==='GET')return json({npcs:NPCS.map(n=>({...n,is_npc:true})),recommended:NPCS.reduce((best,n)=>Math.abs(n.rating-me.rating)<Math.abs(best.rating-me.rating)?n:best).id});
if(path==='/api/games'&&method==='GET')return json({games:await all("SELECT g.id,g.black,g.ranked,g.created_at,p.handle,p.name,p.rating,p.color FROM games g JOIN profiles p ON p.id=g.black WHERE g.status='waiting' AND g.invited IS NULL ORDER BY g.created_at DESC LIMIT 30")});
if(path==='/api/games'&&method==='POST'){if(body.ranked!==undefined&&typeof body.ranked!=='boolean')fail('Choose ranked or free play.');let ranked=body.ranked===false?0:1;let existing=await one("SELECT id FROM games WHERE (black=? OR white=?) AND status IN ('waiting','active')",id,id);if(existing)fail('Finish or cancel your current online game first.');if(body.npcId){let npc=NPCS.find(n=>n.id===body.npcId);if(!npc)fail('Choose a valid NPC opponent.');if(!ranked)fail('NPC ladder games are ranked. Use Practice for unrated computer games.');if(body.handle)fail('Choose a friend or an NPC opponent.');let npcProfile='npc:'+npc.id,npcHandle=npc.handle;if(await one('SELECT id FROM profiles WHERE handle=? AND id<>?',npcHandle,npcProfile))npcHandle=npc.handle+'_'+crypto.randomUUID().slice(0,6);await run('INSERT OR IGNORE INTO profiles(id,handle,name,bio,color,rating,is_npc) VALUES(?,?,?,?,?,?,1)',npcProfile,npcHandle,npc.name,npc.bio,npc.color,npc.rating);let gid=crypto.randomUUID();await run("INSERT INTO games(id,black,white,status,ranked,npc_id) VALUES(?,?,?,'active',1,?)",gid,id,npcProfile,npc.id);return json({id:gid})}let invited=null;if(body.handle){let p=await one('SELECT id FROM profiles WHERE handle=? COLLATE NOCASE',String(body.handle));if(!p||p.id===id)fail('Choose another registered player.');let f=await one("SELECT sender FROM friendships WHERE status='accepted' AND ((sender=? AND receiver=?) OR (sender=? AND receiver=?))",id,p.id,p.id,id);if(!f)fail('Add this player as a friend before challenging them.');invited=p.id}let gid=crypto.randomUUID();await run('INSERT INTO games(id,black,invited,ranked) VALUES(?,?,?,?)',gid,id,invited,ranked);return json({id:gid})}
