async function publicDaily(req){let url=new URL(req.url),path=url.pathname,p=dailyPuzzle();if(req.method==='GET'&&path==='/api/daily')return json({daily:puzzleView(p),resetsAt:new Date(Date.parse(p.id.slice(6)+'T00:00:00Z')+86400000).toISOString()});if(req.method!=='POST'||!['/api/daily/attempt','/api/daily/hint'].includes(path))return json({error:'Not found'},404);if(req.headers.get('Origin')&&req.headers.get('Origin')!==url.origin)fail('Request origin is not allowed.',403);let body;try{body=await req.json()}catch{fail('Send a valid request.')}if(body.id!==p.id)fail('A new daily puzzle is ready. Return to the puzzle hub.');if(path.endsWith('/hint'))return json({hint:p.hint});let choices=body.moves;if(!Array.isArray(choices)||choices.length<1||choices.length>p.steps||choices.some(i=>!Number.isInteger(i)||i<0||i>=225))fail('Invalid puzzle attempt.');let correct=choices[0]===p.first,solved=correct&&p.steps===1;if(correct&&p.steps===2){if(choices.length===1)return json({correct:true,solved:false,reply:p.reply,message:'Good. They blocked one line. Now finish the game.'});let b=Array(225).fill(0);p.black.forEach(i=>b[i]=1);p.white.forEach(i=>b[i]=2);b[p.first]=1;b[p.reply]=2;let i=choices[1];if(!b[i]){b[i]=1;let r=Math.floor(i/15),c=i%15;solved=DIRECTIONS.some(([dr,dc])=>{let n=1;for(let sign of [-1,1])for(let k=1;k<5;k++){let y=r+dr*k*sign,x=c+dc*k*sign;if(y<0||x<0||y>=15||x>=15||b[y*15+x]!==1)break;n++}return n>=5})}correct=solved}return json({correct,solved,message:solved?'Beautifully played. Puzzle solved.':'Not quite. Look for a stronger move.'})}
export default {async fetch(req,env){let ctx={cookies:[]};let response;try{let u=new URL(req.url);if(u.pathname==='/api/daily'||u.pathname.startsWith('/api/daily/'))response=await publicDaily(req);else if(u.pathname.startsWith('/api/auth/'))response=await authRoute(req,env,ctx);else if(u.pathname.startsWith('/api/')){let user=await authenticatedUser(req,env,ctx);if(!user)fail('Sign in with your email and password to continue.',401);if(!env.DB)fail('The club database is not connected yet.',503);let id=await clubIdentity(req,env,user);response=await api(req,env,id)}else{let asset=ASSETS[u.pathname];response=asset?new Response(asset.body,{headers:{'Content-Type':asset.type+'; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'}}):new Response('Not found',{status:404})}}catch(e){if(e.status)response=json({error:e.message},e.status);else{console.error('Club request failed');response=json({error:'Something went wrong. Please try again.'},500)}}for(let c of ctx.cookies)response.headers.append('Set-Cookie',c);return response}};
